{
  "name": "@vueuse/integrations",
  "type": "module",
  "version": "15.0.0",
  "description": "Integration wrappers for utility libraries",
  "author": "Anthony Fu <https://github.com/antfu>",
  "license": "MIT",
  "funding": "https://github.com/sponsors/antfu",
  "homepage": "https://github.com/vueuse/vueuse/tree/main/packages/integrations#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/vueuse/vueuse.git",
    "directory": "packages/integrations"
  },
  "bugs": {
    "url": "https://github.com/vueuse/vueuse/issues"
  },
  "keywords": [
    "vue",
    "vue-use",
    "utils"
  ],
  "sideEffects": false,
  "exports": {
    ".": "./dist/index.js",
    "./*": "./dist/*",
    "./useAsyncValidator": "./dist/useAsyncValidator.js",
    "./useAsyncValidator/component": "./dist/useAsyncValidator/component.js",
    "./useAxios": "./dist/useAxios.js",
    "./useChangeCase": "./dist/useChangeCase.js",
    "./useCookies": "./dist/useCookies.js",
    "./useDrauu": "./dist/useDrauu.js",
    "./useFocusTrap": "./dist/useFocusTrap.js",
    "./useFocusTrap/component": "./dist/useFocusTrap/component.js",
    "./useFuse": "./dist/useFuse.js",
    "./useIDBKeyval": "./dist/useIDBKeyval.js",
    "./useJwt": "./dist/useJwt.js",
    "./useNProgress": "./dist/useNProgress.js",
    "./useQRCode": "./dist/useQRCode.js",
    "./useSortable": "./dist/useSortable.js",
    "./useSortable/component": "./dist/useSortable/component.js",
    "./package.json": "./package.json"
  },
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "unpkg": "./dist/index.iife.min.js",
  "jsdelivr": "./dist/index.iife.min.js",
  "types": "./dist/index.d.ts",
  "files": [
    "dist"
  ],
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "build": "tsdown",
    "prepack": "pnpm run build"
  },
  "peerDependencies": {
    "async-validator": "^4",
    "axios": "^1",
    "change-case": "^5",
    "drauu": "^1 || ^0.4",
    "focus-trap": "^7 || ^8",
    "fuse.js": "^7",
    "idb-keyval": "^6",
    "jwt-decode": "^4",
    "nprogress": "^0.2",
    "qrcode": "^1.5",
    "sortablejs": "^1",
    "universal-cookie": "^7 || ^8",
    "vue": "^3.5.0"
  },
  "peerDependenciesMeta": {
    "async-validator": {
      "optional": true
    },
    "axios": {
      "optional": true
    },
    "change-case": {
      "optional": true
    },
    "drauu": {
      "optional": true
    },
    "focus-trap": {
      "optional": true
    },
    "fuse.js": {
      "optional": true
    },
    "idb-keyval": {
      "optional": true
    },
    "jwt-decode": {
      "optional": true
    },
    "nprogress": {
      "optional": true
    },
    "qrcode": {
      "optional": true
    },
    "sortablejs": {
      "optional": true
    },
    "universal-cookie": {
      "optional": true
    }
  },
  "dependencies": {
    "@vueuse/core": "workspace:*",
    "@vueuse/shared": "workspace:*"
  },
  "devDependencies": {
    "@types/nprogress": "catalog:types",
    "@types/qrcode": "catalog:types",
    "@types/sortablejs": "catalog:types",
    "async-validator": "catalog:integrations",
    "axios": "catalog:integrations",
    "change-case": "catalog:integrations",
    "drauu": "catalog:integrations",
    "focus-trap": "catalog:integrations",
    "fuse.js": "catalog:integrations",
    "idb-keyval": "catalog:integrations",
    "jwt-decode": "catalog:integrations",
    "nprogress": "catalog:integrations",
    "qrcode": "catalog:integrations",
    "sortablejs": "catalog:integrations",
    "universal-cookie": "catalog:integrations"
  }
}
